export type PostTopic = {
  id: string;
  title: string;
  value: string;
};

export type PostFilter = {
  /** topics: tabs above the posts; the page filters by `topic` */
  mode?: "none" | "topics";
  /** the topic tabs */
  topics?: PostTopic[];
  /** accessible name of the topic tabs */
  label?: string;
  /** the value of the chosen topic; empty: all posts */
  topic?: string;
};
